<?php
declare(strict_types=1);
require_once __DIR__.'/Support/TemporaryUsageIdentity.php';
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/CommercialCostKpiTest.php';
use DigiForge\Core\Settings;
use DigiForge\Database\Tables;
final class OperatorOverviewAcceptanceTest extends WP_UnitTestCase {
 private ?Closure $isolatedScope=null;private array $isolatedTables=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],DigiForge\Core\Capabilities::ALL);global $wpdb;$next=TemporaryUsageIdentity::next($this);foreach([Tables::shop_ai_usage(),Tables::shop_ai_policies()]as $table){$temporary=$table.'_'.substr(str_replace('-','',wp_generate_uuid4()),0,12);self::assertNotFalse($wpdb->query('CREATE TEMPORARY TABLE '.$temporary.' LIKE '.$table));$this->isolatedTables[$table]=$temporary;}self::assertNotFalse($wpdb->query('ALTER TABLE '.$this->isolatedTables[Tables::shop_ai_usage()].' AUTO_INCREMENT = '.$next));$tables=$this->isolatedTables;$this->isolatedScope=static fn(string $sql):string=>str_replace(array_keys($tables),array_values($tables),$sql);add_filter('query',$this->isolatedScope,1);}
 protected function tearDown():void {if($this->isolatedScope!==null)remove_filter('query',$this->isolatedScope,1);global $wpdb;foreach($this->isolatedTables as $table)$wpdb->query('DROP TEMPORARY TABLE IF EXISTS '.$table);parent::tearDown();}
 private function render(string $view,array $extra=[]):string {$before=$_GET;try{$_GET=['df_view'=>$view,'df_shop'=>'digital']+$extra;return (new DigiForge\Portal\Portal())->render();}finally{$_GET=$before;}}
 private function alert(string $state):array {
  global $wpdb;$marker='offline_alert_'.wp_rand();$now=current_time('mysql',true);$evidence=wp_json_encode(['private_fixture_note'=>'must_not_display_'.$marker]);
  self::assertSame(1,$wpdb->insert(Tables::operational_alerts(),['environment'=>'sandbox','alert_type'=>$marker,'source_type'=>'research','source_id'=>0,'severity'=>'WARNING','evidence'=>$evidence,'evidence_hash'=>hash('sha256',(string)$evidence),'state'=>$state,'created_at'=>$now,'updated_at'=>$now]));return ['id'=>(int)$wpdb->insert_id,'marker'=>$marker];
 }
 public function testGlobalAlertOverviewDrillsIntoExactOpenEvidenceAndPreservesItsState():void {
  global $wpdb;$table=Tables::operational_alerts();$before=(int)$wpdb->get_var("SELECT COUNT(*) FROM $table WHERE state NOT IN ('RESOLVED','DISMISSED','SUPERSEDED','CLOSED')");$open=$this->alert('OPEN');$closed=$this->alert('RESOLVED');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE id=%d",$open['id']),ARRAY_A);
  $dashboard=$this->render('dashboard');self::assertStringContainsString('<span>Open operational alerts</span><strong>'.($before+1).'</strong>',$dashboard);self::assertStringContainsString('df_view=attention',$dashboard);self::assertStringContainsString('Dashboard counts remain authoritative global counts',$dashboard);
  $attention=$this->render('attention',['df_alert_id'=>(string)$open['id']]);self::assertStringContainsString('id="df-alert-'.$open['id'].'"',$attention);self::assertStringContainsString($open['marker'],$attention);self::assertStringNotContainsString($closed['marker'],$attention);self::assertStringNotContainsString('must_not_display_'.$open['marker'],$attention);self::assertStringContainsString('WARNING',$attention);self::assertStringContainsString('External execution authority',$attention);self::assertSame($row,$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE id=%d",$open['id']),ARRAY_A));self::assertTrue(Settings::safety_locked());
 }
 public function testUnavailableAlertsCannotBecomeZeroOrAnEmptyRecoveryQueue():void {
  global $wpdb;$table=Tables::operational_alerts();$filter=static fn(string $sql):string=>str_contains($sql,'FROM '.$table)?'SELECT * FROM nonexistent_operator_alert_fixture':$sql;$previous=$wpdb->suppress_errors(true);add_filter('query',$filter);try{$dashboard=$this->render('dashboard');self::assertStringContainsString('<span>Open operational alerts</span><strong>UNAVAILABLE</strong>',$dashboard);self::assertStringNotContainsString('<span>Open operational alerts</span><strong>0</strong>',$dashboard);$attention=$this->render('attention');self::assertStringContainsString('Operational alert evidence unavailable',$attention);self::assertStringNotContainsString('No open operational alerts.',$attention);}finally{remove_filter('query',$filter);$wpdb->suppress_errors($previous);}
 }
 public function testPartialShopAssignmentsCannotReadGlobalOverviewOrAttention():void {
  ShopAccessFixture::reset();ShopAccessFixture::authorizeActor(get_current_user_id(),['digital'],DigiForge\Core\Capabilities::ALL);$reads=0;$filter=static function(string $sql)use(&$reads):string{foreach([Tables::operational_alerts(),Tables::orders(),Tables::research_candidates()] as $table)if(str_contains($sql,'FROM '.$table))++$reads;return $sql;};add_filter('query',$filter);try{foreach(['dashboard','attention']as $view){$html=$this->render($view);self::assertStringContainsString('requires assignments for all four shops',$html);self::assertStringNotContainsString('df-stat-card',$html);}self::assertSame(0,$reads);}finally{remove_filter('query',$filter);}
 }
 private function commercialFixture(bool $settle=true):array {$fixture=new CommercialCostKpiTest('testReviewedProviderChargeJoinsExactStoredCommercialLineage');return (new ReflectionMethod($fixture,'fixture'))->invoke($fixture,$settle);}
 public function testDashboardShowsStoredAndReviewedCostsWithoutOtherShopAmounts():void {
  $fixture=$this->commercialFixture();$foreign=(new DigiForge\AI\ShopAiGovernanceRepository())->recordUsage(['shop_key'=>'jewelry','stage'=>'develop','quantity'=>9,'estimated_cost'=>987.654321,'actual_cost'=>876.543210,'currency'=>'USD']);self::assertNotWPError($foreign);
  $html=$this->render('dashboard');$directory=getenv('DF_PORTAL_FIXTURE_DIR');if(is_string($directory)&&$directory!=='')self::assertSame(strlen($html),file_put_contents($directory.'/portal-dashboard--digital.html',$html));self::assertStringContainsString('Selected-shop AI spend evidence',$html);self::assertStringContainsString('Reviewed commercial AI cost',$html);self::assertStringContainsString('0.120000',$html);self::assertStringContainsString('FINANCE_DEFERRED',$html);self::assertStringContainsString('all retained periods',$html);self::assertStringContainsString('end exclusive',$html);self::assertStringNotContainsString('987.654321',$html);self::assertStringNotContainsString('876.543210',$html);self::assertFalse(DigiForge\Portal\DashboardCostPanel::snapshot('digital')['external_execution_authorized']);self::assertGreaterThan(0,$fixture['usage']['id']);
 }
 public function testPendingChargeAndFaultCannotBecomeReviewedZero():void {
  $this->commercialFixture(false);$data=DigiForge\Portal\DashboardCostPanel::snapshot('digital');self::assertSame('AVAILABLE',$data['query_state']);$html=$this->render('dashboard');self::assertStringContainsString('Recorded zero can exclude pending or missing provider charges',$html);self::assertStringContainsString('UNAVAILABLE',$html);self::assertStringNotContainsString('<td>0.000000</td>',$html);
  global $wpdb;$table=Tables::shop_ai_usage();$filter=static fn(string $sql):string=>str_contains($sql,'FROM '.$table)?'SELECT * FROM missing_dashboard_spend_fixture':$sql;$previous=$wpdb->suppress_errors(true);add_filter('query',$filter);try{self::assertSame('UNAVAILABLE',DigiForge\Portal\DashboardCostPanel::snapshot('digital')['query_state']);self::assertStringContainsString('Selected-shop spend evidence unavailable',$this->render('dashboard'));}finally{remove_filter('query',$filter);$wpdb->suppress_errors($previous);}
 }
 public function testUnavailableScopeOrMissingUsageNeverQueriesOrCertifiesZero():void {
  $emptyScope=static fn(string $sql):string=>str_replace("WHERE shop_key='standard_pod'","WHERE shop_key='standard_pod' AND 1=0",$sql);add_filter('query',$emptyScope);try{$empty=DigiForge\Portal\DashboardCostPanel::snapshot('standard_pod');}finally{remove_filter('query',$emptyScope);}self::assertSame('UNAVAILABLE',$empty['query_state']);self::assertNull($empty['totals']);
  $this->commercialFixture();$reads=0;$filter=static function(string $sql)use(&$reads):string{if(str_contains($sql,'FROM '.Tables::shop_ai_usage()))++$reads;return $sql;};add_filter('query',$filter);try{foreach(['all','unknown']as $shop)self::assertSame('UNAVAILABLE',DigiForge\Portal\DashboardCostPanel::snapshot($shop)['query_state']);self::assertSame(0,$reads);ShopAccessFixture::reset();ShopAccessFixture::authorizeActor(get_current_user_id(),['digital'],['manage_digiforge']);self::assertSame('UNAVAILABLE',DigiForge\Portal\DashboardCostPanel::snapshot('digital')['query_state']);self::assertSame(0,$reads);}finally{remove_filter('query',$filter);}
 }

 public function testRetainedImmutableMeteringCannotBeReusedAfterTemporaryUsageRowsDisappear():void {
  $fixture=$this->commercialFixture();$id=(int)$fixture['usage']['id'];global $wpdb;$name='digiforge_ai_evidence_completion_'.$id;$before=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$name));self::assertIsString($before);
  remove_filter('query',$this->isolatedScope,1);try{$oldNext=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0)+1000 FROM '.Tables::shop_ai_usage());self::assertLessThanOrEqual($id,$oldNext);self::assertGreaterThan($id,TemporaryUsageIdentity::next($this));self::assertSame($before,$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$name)));}finally{add_filter('query',$this->isolatedScope,1);}
 }

}
